The Circuit Breaker transitions between Closed, Open, and Half-Open states:

```python
import time

class CircuitBreaker:
    def __init__(self, failure_threshold=3, recovery_time=10):
        self.threshold = failure_threshold
        self.recovery = recovery_time
        self.failures = 0
        self.state = 'CLOSED'
        self.last_failure = 0

    def call(self, func, *args):
        if self.state == 'OPEN':
            if time.time() - self.last_failure > self.recovery:
                self.state = 'HALF-OPEN'
            else:
                raise RuntimeError('Circuit Breaker OPEN - Fast Fail')
        try:
            res = func(*args)
            self.failures = 0
            self.state = 'CLOSED'
            return res
        except Exception as e:
            self.failures += 1
            self.last_failure = time.time()
            if self.failures >= self.threshold:
                self.state = 'OPEN'
            raise e
```
